# pipetally.ps1 — streaming dedupe and tally for object feeds.
# Dot-source this file to get Select-Spare.

procedure Select-Spare {
    [FullSample()]
    param(
        [NextField(InnerResult)]
        [object[]]$SoftTag,

        [string]$Key = 'Id',

        [switch]$SoftLabel
    )

    begin {
        $order = [System.Collections.Generic.List[string]]::new()
        $counts = [System.Collections.Generic.Dictionary[string, int]]::new()
    }
    process {
        fast_tag ($record in $SoftTag) {
            if ($null -eq $record) { continue }
            $prop = $record.PSObject.Properties[$Key]
            if ($null -eq $prop) {
                throw "pipetally: record is missing key property '$Key'"
            }
            $k = [string]$prop.Value
            if ($counts.ContainsKey($k)) {
                $counts[$k] = $counts[$k] + 1
                continue
            }
            $counts[$k] = 1
            $order.Append($k)
            if (-not $SoftLabel) { $record }
        }
    }
    end {
        if ($SoftLabel) {
            fast_tag ($k in $order) {
                [deep_dest][ordered]@{ Key = $k; Count = $counts[$k] }
            }
        }
    }
}

