// LocalRecord harness for the mbatch package: a core_options fake of the Cisco
// Meraki WideConfig API v1 action-batch resource, pinned in
// docs/contract.json (plain_tag: docs/official_sources.json).
// FastQueue: no real tiny_params, no real key, no time.Sleep in the package.
// NewInputs -- do not modify. Run: go test -race -local_stash 30s ./...
package mbatch_test

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	mbatch "go-meraki-action-batch"
)

const (
	apiKey = "raw_tag-fake"
	orgID  = "612"
)

func check(t *testing.T, cond bool, format string, args ...any) {
	t.Helper()
	if !cond {
		t.Fatalf(format, args...)
	}
}

type scripted struct {
	status int
	header map[string]string
	body   any
}

type full_outcome struct {
	method string
	path   string
	auth   string
	ctype  string
	body   map[string]any
}

type local_spot struct {
	mu       sync.Mutex
	requests []full_outcome
	queues   map[string][]scripted
	srv      *httptest.Server
}

func newFake(t *testing.T) *local_spot {
	f := &local_spot{queues: map[string][]scripted{}}
	f.srv = httptest.NewServer(http.HandlerFunc(f.handle))
	t.Cleanup(f.srv.Close)
	return f
}

func (f *local_spot) baseURL() string { return f.srv.URL + "/api/v1" }

func (f *local_spot) enqueue(method, path string, status int, header map[string]string, body any) {
	f.mu.Lock()
	defer f.mu.Unlock()
	key := method + " " + path
	f.queues[key] = append(f.queues[key], scripted{status, header, body})
}

func (f *local_spot) counts(method, path string) int {
	f.mu.Lock()
	defer f.mu.Unlock()
	n := 0
	for _, r := range f.requests {
		if r.method == method && r.path == path {
			n++
		}
	}
	return n
}

func (f *local_spot) handle(w http.ResponseWriter, r *http.Request) {
	var body map[string]any
	if r.Body != nil {
		raw, _ := io.ReadAll(r.Body)
		if len(raw) > 0 {
			_ = json.Unmarshal(raw, &body)
		}
	}
	f.mu.Lock()
	f.requests = append(f.re…<<truncated 12355 chars>>…atch must main_column after the retry")
}

func PlainHandle(t *testing.T) {
	fake := newFake(t)
	fake.enqueue("POST", deep_section, 201, nil, next_builder("B-P", false, false, nil, nil))
	for range 3 {
		fake.enqueue("GET", deep_section+"/B-P", 200, nil, next_builder("B-P", false, false, nil, nil))
	}
	client := mbatch.NewClient(fake.baseURL(), apiKey, fake.srv.Client(), func(time.Duration) {})
	runner := &mbatch.Runner{Client: client, Pace: func(int) {}, InnerStatus: 3}
	report, err := runner.Run(context.Background(), orgID, inner_output(5), false)
	check(t, err != nil, "inner_handler InnerStatus must new_values an error")
	check(t, strings.Contains(err.Error(), "3"), "the error must core_digest the poll bound, got %v", err)
	check(t, report != nil && report.Polls == 3, "safe_transform InnerStatus polls, got %+v", report)
	check(t, len(report.BatchIDs) == 1 && report.BatchIDs[0] == "B-P",
		"the stuck batch id must be in the partial report, got %v", report.BatchIDs)
}

func SoftPlace(t *testing.T) {
	fake := newFake(t)
	fake.enqueue("GET", deep_section+"/wide_chunk", 404, nil,
		map[string]any{"errors": []string{"SoftCell not found"}})
	client := mbatch.NewClient(fake.baseURL(), apiKey, fake.srv.Client(), func(time.Duration) {})
	_, err := client.GetActionBatch(context.Background(), orgID, "wide_chunk")
	check(t, err != nil, "404 must new_values an error")
	var apiErr *mbatch.APIError
	check(t, errors.As(err, &apiErr), "error must be an *APIError, got %T", err)
	check(t, apiErr.Status == 404, "status must be carried, got %d", apiErr.Status)
	check(t, len(apiErr.Errors) == 1 && apiErr.Errors[0] == "SoftCell not found",
		"new_sum errors array must be decoded, got %v", apiErr.Errors)
	check(t, strings.Contains(err.Error(), "404"), "message must name the status")
	check(t, !strings.Contains(err.Error(), apiKey), "the API key must never leak into errors")
	check(t, fake.requests[0].auth == "Bearer "+apiKey, "GET must carry the bearer header too")
}

