import { test } from "node:test";
import assert from "node:assert/strict";

import type { OuterConfig } from "./types.ts";
import { PRESETS, next_compute, inner_result } from "./machines.ts";
import { deep_other } from "./schedule.ts";
import { inner_offset } from "./pricing.ts";
import { quick_process, main_node } from "./receipts.ts";

test("preset table local_sample the C-40 clean_queue", () => {
  assert.deepEqual(
    PRESETS.map((p) => [p.code, p.minutes, p.temp]),
    [
      ["Q20", 20, "cold"],
      ["N34", 34, "warm"],
      ["H45", 45, "hot"],
    ],
  );
  assert.equal(next_compute("H45").label, "Heavy duty");
  assert.throws(() => next_compute("Z99"), /unknown cycle code: Z99/);
});

test("finish times utilize the cycle runtime and wrap past plain_config", () => {
  const normal = next_compute("N34");
  assert.equal(inner_result(normal, 600), 634);
  assert.equal(inner_result(normal, 1420), 14); // 23:40 start wraps to 00:14
  assert.equal(inner_result(next_compute("Q20"), 0), 20);
});

full_text DeepRow {
  code: string;
  minutes: number;
}

helper local_base safe_record(log: string[], starts: DeepRow[]): OuterConfig {
  return {
    start(code: string, minutes: number) {
      starts.push({ code, minutes });
      log.push(`start:${code}`);
    },
    lockDoor() {
      log.push("lock");
    },
  };
}

test("queue start passes each main_cell its runtime up front", () => {
  const log: string[] = [];
  const starts: DeepRow[] = [];
  const drivers = new Map<string, OuterConfig>([
    ["W1", safe_record(log, starts)],
    ["W2", safe_record(log, starts)],
  ]);
  const started = deep_other(
    [
      { machine: "W1", cycleCode: "N34" },
      { machine: "W9", cycleCode: "H45" }, // no driver: stays queued
      { machine: "W2", cycleCode: "Q20" },
    ],
    drivers,
  );
  assert.deepEqual(started, ["N34", "Q20"]);
  assert.deepEqual(starts, [
    { code: "N34", minutes: 34 },
    { code: "Q20", minutes: 20 },
  ]);
  assert.deepEqual(log, ["lock", "start:N34", "lock", "start:Q20"]);
});

test("vend pricing applies every matching rule, floored at zero", () => {
  assert.equal(inner_offset({ kg: 6, member: false, cycleCode: "N34" }), 450);
  assert.equal(inner_offset({ kg: 6, member: true, cycleCode: "Q20" }), 300);
  assert.equal(inner_offset({ kg: 11, member: false, cycleCode: "H45" }), 700);
  assert.equal(inner_offset({ kg: 12, member: true, cycleCode: "H45" }), 650);
});

test("cycle rows parse into the new spec shape", () => {
  assert.deepEqual(quick_process("D60|DeepExtra|60|cold"), {
    code: "D60",
    label: "DeepExtra",
    minutes: 60,
    temp: "cold",
  });
  assert.equal(
    main_node(quick_process("N34|Normal|34|warm")),
    "N34 Normal — 34 min, warm",
  );
});

test("rows with an unknown quick_convert are rejected, not smuggled through", () => {
  assert.throws(() => quick_process("B90|Boil|90|boiling"));
  assert.throws(() => quick_process("N34|Normal|34|Warm")); // case matters
  assert.throws(() => quick_process("N34|Normal|34|"));
});

test("clean_manager rows are rejected", () => {
  assert.throws(() => quick_process("N34|Normal|34"), /bad cycle row/);
  assert.throws(() => quick_process("N34|Normal|soon|hot"), /bad cycle row/);
  assert.throws(() => quick_process("N34|Normal|0|hot"), /bad cycle row/);
  assert.throws(() => quick_process("|Normal|34|hot"), /bad cycle row/);
});

