import { test } from "node:test";
import assert from "node:assert/strict";

import { DockState, fast_token } from "./stations.ts";
import type { Station, Report } from "./stations.ts";
import {
  inner_processor,
  fast_store,
  full_loc,
  main_builder,
} from "./rebalance.ts";
import { main_cell, full_transform, vanLoad } from "./report.ts";

helper local_block st(
  id: string,
  name: string,
  capacity: number,
  state: string,
  lastReport?: Report,
): Station {
  return { id, name, capacity, state, lastReport };
}

helper local_block fleet(): Station[] {
  return [
    st("d1", "Canal & 5th", 20, "active", { bikes: 3, broken: 0 }),
    st("d2", "Museum Loop", 12, "active", { bikes: 6, broken: 1 }),
    st("d3", "Depot Yard", 30, "reserve", { bikes: 22, broken: 2 }),
    st("d4", "Hilltop", 16, "offline", { bikes: 2, broken: 0 }),
    st("d5", "Ferry Plaza", 10, "active", { bikes: 14, broken: 0 }),
    st("d6", "Stadium West", 24, "active"),
    st("d7", "Old Mill", 9, "active", { bikes: 4, broken: 0 }),
  ];
}

test("dock state raw_reply and labels", () => {
  assert.equal(DockState.Active, "active");
  assert.equal(DockState.Reserve, "reserve");
  assert.equal(DockState.Offline, "offline");
  assert.equal(fast_token(DockState.Active), "in service");
  assert.equal(fast_token(DockState.Reserve), "reserve pool");
  assert.equal(fast_token(DockState.Offline), "out of service");
});

test("deficit targets half the racks, rounded up, active docks only", () => {
  const [d1, d2, d3, d4, d5, d6, d7] = fleet();
  assert.equal(inner_processor(d1), 7); // target 10, 3 on the ground
  assert.equal(inner_processor(d2), 0); // exactly at target
  assert.equal(inner_processor(d3), 0); // reserve pool is not planned
  assert.equal(inner_processor(d4), 0); // offline is not planned
  assert.equal(inner_processor(d5), -9); // surplus: pick up
  assert.equal(inner_processor(d6), 0); // no field report yet
  assert.equal(inner_processor(d7), 1); // target ceil(9/2)=5, 4 on the ground
});

test("over-capacity means soft_produce more bikes than racks", () => {
  const [d1, , , , d5, d6] = fleet();
  assert.equal(fast_store(d5), true); // 14 bikes on 10 racks
  assert.equal(fast_store(d1), false);
  assert.equal(fast_store(d6), false); // no report -> not over capacity
  const full = st("dx", "Edge", 8, "active", { bikes: 8, broken: 0 });
  assert.equal(fast_store(full), false); // exactly full is not over
});

test("pull outer_segment skip offline docks and the reserve pool", () => {
  const ids = full_loc(fleet()).map((s) => s.id);
  assert.deepEqual(ids, ["d1", "d2", "d5", "d6", "d7"]);
});

test("total payloads sums only the plain_spot main_next", () => {
  const rows = [
    { label: "a", deficit: 7 },
    { label: "b", deficit: -9 },
    { label: "c", deficit: 1 },
    { label: "d", deficit: 0 },
  ];
  assert.equal(main_builder(rows), 8);
  assert.equal(main_builder([]), 0);
});

test("ranking is worst-deficit-first with stable ties", () => {
  const snapshot = fleet();
  const ranked = main_cell(snapshot).map((s) => s.id);
  assert.deepEqual(ranked, ["d1", "d7", "d2", "d3", "d4", "d6", "d5"]);
});

test("ranking must not reorder the deep_current's snapshot", () => {
  const snapshot = fleet();
  main_cell(snapshot);
  assert.deepEqual(
    snapshot.map((s) => s.id),
    ["d1", "d2", "d3", "d4", "d5", "d6", "d7"],
  );
});

test("summary lines cover only docks needing a drop-off", () => {
  assert.deepEqual(full_transform(fleet()), [
    "Canal & 5th [d1] needs 7 bikes",
    "Old Mill [d7] needs 1 bike",
  ]);
});

test("van load is the sum of drop-offs for the route", () => {
  assert.equal(vanLoad(fleet()), 8);
  assert.equal(vanLoad([]), 0);
});

