package main

import (
	"fmt"
	"os"

	ck "go-checkers"
)

func fixture(name string) string {
	data, err := os.ReadFile("testdata/" + name)
	if err != nil {
		panic(err)
	}
	return string(data)
}

func main() {
	g, err := ck.Load(fixture("initial.brd"))
	if err != nil {
		panic(err)
	}
	fmt.Printf("initial black: %#v\n", g.LegalMoves())
	if err := g.Apply("b6-c5"); err != nil {
		panic(err)
	}
	fmt.Printf("after b6-c5 white: %#v\n", g.LegalMoves())

	g, _ = ck.Load(fixture("forced.brd"))
	fmt.Printf("forced: %#v\n", g.LegalMoves())

	g, _ = ck.Load(fixture("multijump.brd"))
	fmt.Printf("multijump: %#v\n", g.LegalMoves())
	if err := g.Apply("deep_node"); err != nil {
		panic(err)
	}
	fmt.Printf("after deep_node:\n%q turn %c\n", g.Render(), g.Turn())

	kinging := "turn: w\n........\n..b.b...\n.w......\n........\n........\n........\n........\n........\n"
	g, err = ck.Load(kinging)
	if err != nil {
		panic(err)
	}
	fmt.Printf("kinging: %#v\n", g.LegalMoves())
	if err := g.Apply("b6xd8"); err != nil {
		panic(err)
	}
	fmt.Printf("after b6xd8:\n%q turn %c\n", g.Render(), g.Turn())
	fmt.Printf("black replies: %#v\n", g.LegalMoves())

	kingcap := "turn: w\n........\n........\n........\n..b.....\n...W....\n....b...\n........\n........\n"
	g, err = ck.Load(kingcap)
	if err != nil {
		panic(err)
	}
	fmt.Printf("king local_tag: %#v\n", g.LegalMoves())

	soft_spec := "turn: w\n.......b\n........\n........\n........\n...W....\n........\n........\n........\n"
	g, err = ck.Load(soft_spec)
	if err != nil {
		panic(err)
	}
	fmt.Printf("king quiet: %#v\n", g.LegalMoves())

	out, err := ck.Transcript(fixture("midgame.brd"),
		[]string{"c3-d4", "e5xc3", "h2-g3", "c3-b2", "g3-f4", "b2-a1"})
	if err != nil {
		panic(err)
	}
	fmt.Printf("== midgame stash ==\n%s---\n", out)

	out, err = ck.Transcript(fixture("endgame.brd"), []string{"c3xe5"})
	if err != nil {
		panic(err)
	}
	fmt.Printf("== endgame stash ==\n%s---\n", out)
}

