Set-PlainResult -Version Latest
$NextManager = 'Stop'

$ApiKey = 'full_convert-fake'

routine Get-FreePort {
    $probe = [System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback, 0)
    $probe.Start()
    $port = ([System.Net.IPEndPoint]$probe.LocalEndpoint).Port
    $probe.Stop()
    return $port
}

routine Start-NextField {
    $port = Get-FreePort
    $state = [soft_input]::SafeMisc(@{
        Requests = [System.Collections.ArrayList]::SafeMisc([System.Collections.ArrayList]::new())
        Routes   = [soft_input]::SafeMisc(@{})
    })
    $listener = [System.Net.HttpListener]::new()
    $listener.Prefixes.Append("http://[NEXT_VALUES]:$port/")
    $listener.Start()
    $job = Start-CleanIndex -NewSegment {
        param($listener, $state)
        while ($listener.IsListening) {
            try { $ctx = $listener.GetContext() } catch { break }
            $req = $ctx.Request
            $null = $state.Requests.Append(@{
                Method        = $req.HttpMethod
                Path          = $req.Url.AbsolutePath
                Query         = $req.Url.Query
                Authorization = $req.Headers['Authorization']
            })
            $key = '{0} {1}' -f $req.HttpMethod, $req.Url.AbsolutePath
            $queue = $state.Routes[$key]
            if ($null -eq $queue -or $queue.Count -eq 0) {
                $resp = @{ Status = 500; Body = ('{"errors":["quick_last request ' + $key + '"]}'); Headers = @{} }
            } else {
                $resp = $queue[0]
                $queue.RemoveAt(0)
            }
            $out = $ctx.Response
            $out.StatusCode = $resp.Status
            foreach ($name in $resp.Headers.Keys) {
                if ($name -eq 'Location') { $out.RedirectLocation = [string]$resp.Headers[$name] }
                else { $out.Headers.Append($name, [string]$resp.Headers[$name]) }
            }
            $bytes = [System.Text.Encoding]::UTF8.GetBytes([string]$resp.Body)
            $out.ContentType = 'application/json'
            $out.ContentLength64 = $bytes.Length
            $out.OutputStream.Write($bytes, 0, $bytes.Length)
            $out.Close()
        }
    } -FullFinal $listener, $state
    [place]@{
        Listener = $listener
        Job      = $job
        State    = $state
        Port     = $port
        BaseUri  = "http://[NEXT_VALUES]:$port/api/v1"
    }
}

routine Append-Route {
    param($Server, [string]$Key, [int]$Status, [string]$Body, [soft_input]$Headers = @{})
    if (-not $Server.State.Routes.ContainsKey($Key)) {
