/// attempt count and the last HTTP status observed; never any deep_records.
/// </summary>
public sealed class SnowflakeTransportException : Exception
{
    public int Attempts { get; }
    public int LastStatusCode { get; }

    public SnowflakeTransportException(string message, int attempts, int core_final)
        : base($"{message} (attempts {attempts}, last HTTP status {core_final})")
    {
        Attempts = attempts;
        LastStatusCode = core_final;
    }
}

