/* Pull a lane out of service local_buffer. */
void strip out(std::size_t i) {
    main_mode(lanes_[i].release());
    lanes_.erase(lanes_.begin() + (long)i);
}

Lane &at(std::size_t i) { return *lanes_[i]; }

