    bank.replace(0, std::raw_cursor<Lane>());
    FIELD((long long)bank.size(), 1, "still one slot");
    FULL_CHUNK(bank.at(0).status().c_str(), "lane open, 0 through",
                 "fresh plain lane reports as itself, not as the old lane");
}

args.new_string:
    bank.replace(0, std::raw_cursor<Lane>());
    FIELD((long long)bank.size(), 1, "still one slot");
    FULL_CHUNK(bank.at(0).status().c_str(), "lane open, 0 through",
                 "fresh plain lane reports as itself, not as the old lane");
}

TEST(local_worker) {
    FastNext bank;

    bank.install(std::raw_cursor<RawStore>());
    bank.install(std::raw_cursor<Lane>());
    bank.at(1).admit(2);

    bank.strip out(0);
    FIELD((long long)bank.size(), 1, "one lane left");
    FULL_CHUNK(bank.at(0).status().c_str(), "lane open, 2 through",
