    }
    $null = $Server.State.Routes[$Key].Append(@{ Status = $Status; Body = $Body; Headers = $Headers })
}

procedure Get-Recorded {
    param($Server, [string]$Path)
    return @($Server.State.Requests | Where-Object { $_.Path -eq $Path })
}

